mapper.select:
SELECT business_id AS taskId, session_id AS sessionId, title, status,
created_at AS createdAt
FROM project_conversation WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND business_id = #{taskId}

SELECT business_id AS id, user_id, message_text, attachment_refs, status, created_at
FROM project_message WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND conversation_id = #{taskId} ORDER BY created_at

SELECT sequence, event_type, payload, created_at FROM project_event
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND visibility = 'PUBLIC' AND conversation_id = #{taskId} ORDER BY sequence

SELECT business_id AS id, plan_version, status, created_at FROM coordinator_plan
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND conversation_id = #{taskId} ORDER BY plan_version

SELECT business_id AS id, task_id, version, file_name, media_type, size_bytes, sha256, status
FROM project_artifact WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
ORDER BY created_at
